import itertools

m = 6
R = [0, 1, 2, 3, 4, 5]
weights = list(range(1, m + 1))

def calculate_weighted_sum(perm):
    # perm is a permutation of the indices of R (0 to m-1)
    # We calculate sum( i * R[perm[i]] ) for i=0 to m-1
    return sum((weights[i] * R[perm[i]]) for i in range(m))

found_zero_sum = False
# We only need to iterate over permutations of the indices {0, 1, 2, 3, 4, 5}
# Since R is {0, 1, ..., 5}, we iterate over permutations of R itself for simplicity
for p in itertools.permutations(R):
    current_sum = sum(weights[i] * p[i] for i in range(m))
    if current_sum % m == 0:
        found_zero_sum = True
        print(f"Zero sum found! Permutation: {p}, Sum: {current_sum}")
        break

if not found_zero_sum:
    print("No zero sum found.")

